/**
 * Recompute V1_DATA_DIGEST and write src/data/v1/digest.ts (SPEC 14.2 item 4).
 * Run with `pnpm digest` after an intended v1 data change, and add a changeset that says
 * "ID output changed".
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { computeV1Digest } from '../src/data/v1/profile.ts'

const file = new URL('../src/data/v1/digest.ts', import.meta.url)
const digest = computeV1Digest()
const text = `/**
 * Digest of the v1 data profile (SPEC 14.2 item 4). Generated by \`pnpm digest\`; do not edit by hand.
 * A test recomputes it: any edit to v1 data fails CI until this value is updated on purpose.
 */
export const V1_DATA_DIGEST = '${digest}'
`
const old = (() => {
  try {
    return readFileSync(file, 'utf8')
  } catch {
    return ''
  }
})()
if (old === text) console.log(`V1_DATA_DIGEST unchanged: ${digest}`)
else {
  writeFileSync(file, text)
  console.log(`V1_DATA_DIGEST updated: ${digest}`)
}
